"""Audit labels generated by ``labeler_macd_v01.py``.

The labeler is allowed to read future bars to create a training target. This
script checks that it does not read *beyond* the declared confirmation window:
altering an unrelated future tail must not change earlier labels.

It also reports label balance and the relation between labels and subsequent
returns. These are quality diagnostics, not proof of trading profitability.

Example:
python diagnostic_tools/check_label_leakage.py --csv data/part_2/data_ohlcv_sample/instr_11/2026-08-28.csv \
  --confirm-bars 8 --horizon 12 --weak-thresh 0.05 \
  --spread-threshold-atr 0.1 --growth-threshold-atr 0.1
"""

from __future__ import annotations

import argparse
from dataclasses import asdict, dataclass
from pathlib import Path

import numpy as np
import pandas as pd

from labeler_macd_v01 import build_labels, normalize_df, resample_bars


LABEL_NAMES = {0: "DOWN", 1: "FLAT", 2: "UP"}
PRICE_COLUMNS = ["open", "high", "low", "close"]


@dataclass(frozen=True)
class LabelSettings:
    confirm_bars: int
    horizon: int
    weak_thresh: float
    spread_threshold_atr: float
    growth_threshold_atr: float


def parse_arguments():
    parser = argparse.ArgumentParser(
        description="Check causality and basic quality of labeler_macd_v01 labels."
    )
    parser.add_argument("--csv", required=True, help="Input OHLCV CSV used by the labeler.")
    parser.add_argument("--resample", type=int, default=1, help="Same resampling setting as the labeler.")
    parser.add_argument("--confirm-bars", type=int, default=3)
    parser.add_argument("--horizon", type=int, default=12)
    parser.add_argument("--weak-thresh", type=float, default=0.02)
    parser.add_argument("--spread-threshold-atr", type=float, default=0.02)
    parser.add_argument("--growth-threshold-atr", type=float, default=0.01)
    parser.add_argument("--trials", type=int, default=8,
                        help="Independent future-tail mutation tests (default: 8).")
    parser.add_argument("--labels-out", help="Optional path for regenerated timestamp,label CSV.")
    return parser.parse_args()


def make_settings(args) -> LabelSettings:
    if args.confirm_bars <= 0:
        raise ValueError("--confirm-bars must be positive")
    if args.horizon < args.confirm_bars:
        raise ValueError("--horizon must be at least --confirm-bars")
    if args.resample <= 0 or args.trials <= 0:
        raise ValueError("--resample and --trials must be positive")
    return LabelSettings(
        confirm_bars=args.confirm_bars,
        horizon=args.horizon,
        weak_thresh=args.weak_thresh,
        spread_threshold_atr=args.spread_threshold_atr,
        growth_threshold_atr=args.growth_threshold_atr,
    )


def load_bars(csv_path: str, resample_minutes: int) -> pd.DataFrame:
    """Use precisely the same normalisation and resampling as the labeler."""
    raw = pd.read_csv(csv_path)
    if "timestamp" in raw.columns and "ts" not in raw.columns:
        raw = raw.rename(columns={"timestamp": "ts"})
    raw_count = len(raw)
    duplicate_count = int(raw["ts"].duplicated().sum()) if "ts" in raw else 0
    bars = normalize_df(raw)
    if resample_minutes > 1:
        bars = resample_bars(bars, resample_minutes)
    if len(bars) < 3:
        raise ValueError("Need at least three valid OHLCV bars")
    print(f"Loaded {len(bars):,} usable bars "
          f"(raw rows={raw_count:,}, duplicate timestamps removed={duplicate_count:,}).")
    return bars.reset_index(drop=True)


def generate_labels(bars: pd.DataFrame, settings: LabelSettings) -> pd.DataFrame:
    labels = build_labels(bars, **asdict(settings))
    if labels.empty:
        raise ValueError("The labeler produced no labels with these settings.")
    if labels["ts"].duplicated().any():
        raise AssertionError("The labeler produced duplicate timestamps.")
    if not labels["label"].isin(LABEL_NAMES).all():
        raise AssertionError("The labeler produced an invalid class code.")
    return labels


def attach_row_number(bars: pd.DataFrame, labels: pd.DataFrame) -> pd.DataFrame:
    """Associate each label timestamp with its source-bar position."""
    source = bars[["ts", "close"]].copy()
    source["row_number"] = np.arange(len(source))
    report = labels.merge(source, on="ts", how="left", validate="one_to_one")
    if report["row_number"].isna().any():
        raise AssertionError("A generated label does not match a source bar.")
    report["row_number"] = report["row_number"].astype(int)
    return report


def report_time_integrity(bars: pd.DataFrame, resample_minutes: int) -> None:
    expected = pd.Timedelta(minutes=resample_minutes)
    intervals = bars["ts"].diff().dropna()
    gaps = intervals[intervals > expected]
    print("\nTime-series integrity")
    print(f"  Timestamp range: {bars['ts'].iloc[0]} to {bars['ts'].iloc[-1]}")
    print(f"  Intervals larger than {expected}: {len(gaps):,}")
    print(f"  Non-increasing intervals: {(intervals <= pd.Timedelta(0)).sum():,}")
    if len(gaps):
        print("  Note: overnight/session gaps are expected; intraday gaps need investigation.")


def report_effective_horizon(settings: LabelSettings) -> None:
    print("\nLabeler look-ahead")
    print(f"  Configured horizon: {settings.horizon} bars")
    print(f"  Confirmation bars: {settings.confirm_bars} bars")
    if settings.horizon > settings.confirm_bars:
        print("  Important: classify_future_macd() reads only the first confirmation bars.")
        print("  The larger horizon reduces labels near file end; it does not extend")
        print("  the information used to assign an individual label.")


def report_distribution(labels: pd.DataFrame) -> None:
    counts = labels["label"].value_counts().reindex([0, 1, 2], fill_value=0)
    print("\nLabel distribution")
    for code, count in counts.items():
        print(f"  {LABEL_NAMES[code]:<4} {count:>7,}  ({count / len(labels):6.2%})")
    if (counts / len(labels)).max() > 0.90:
        print("  WARNING: one class exceeds 90%; inspect thresholds and market coverage.")


def report_return_sanity(bars: pd.DataFrame, label_rows: pd.DataFrame,
                         settings: LabelSettings) -> None:
    """Show price returns at the labeler's effective confirmation distance."""
    close = bars["close"].to_numpy(dtype=float)
    source_index = label_rows["row_number"].to_numpy(dtype=int)
    future_index = source_index + settings.confirm_bars
    valid = future_index < len(close)
    rows = label_rows.loc[valid, ["label"]].copy()
    rows["return"] = close[future_index[valid]] / close[source_index[valid]] - 1.0

    print("\nReturn sanity check")
    print(f"  Close-to-close returns after {settings.confirm_bars} bar(s).")
    summary = rows.groupby("label")["return"].agg(["count", "mean", "median"])
    positive = rows.groupby("label")["return"].apply(lambda values: float((values > 0).mean()))
    for code in (0, 1, 2):
        if code in summary.index:
            values = summary.loc[code]
            print(f"  {LABEL_NAMES[code]:<4} n={int(values['count']):>7,} "
                  f"mean={values['mean']:>8.3%} median={values['median']:>8.3%} "
                  f"positive={positive.loc[code]:6.2%}")
    print("  This is a diagnostic only: MACD labels need not equal return labels.")


def mutate_future_tail(bars: pd.DataFrame, first_changed_row: int) -> pd.DataFrame:
    """Change only a future suffix while preserving valid OHLC relationships."""
    changed = bars.copy()
    changed.loc[first_changed_row:, PRICE_COLUMNS] *= 1.73
    return changed


def tail_independence_test(bars: pd.DataFrame, baseline: pd.DataFrame,
                           settings: LabelSettings, trials: int) -> bool:
    """Later data must not alter labels whose confirmation window is complete."""
    baseline_rows = attach_row_number(bars, baseline).set_index("ts")
    first_cut = settings.horizon + settings.confirm_bars + 20
    last_cut = len(bars) - 20
    if first_cut >= last_cut:
        raise ValueError("Not enough bars for the requested tail-independence audit.")
    cuts = np.unique(np.linspace(first_cut, last_cut, num=trials, dtype=int))

    print("\nFuture-tail independence (leakage) test")
    print("  Prices after several cut points are altered. Earlier labels must not change.")
    total_checked, failures = 0, []
    for cut in cuts:
        changed = generate_labels(mutate_future_tail(bars, cut), settings).set_index("ts")
        safe = baseline_rows[baseline_rows["row_number"] + settings.confirm_bars < cut]
        compared = safe[["label"]].join(changed[["label"]], how="left", rsuffix="_changed")
        mismatched = compared[compared["label"] != compared["label_changed"]]
        missing = int(compared["label_changed"].isna().sum())
        total_checked += len(compared)
        print(f"  Cut at row {cut:>6,}: checked {len(compared):>6,}, "
              f"mismatches {len(mismatched):>4,}")
        if len(mismatched) or missing:
            failures.append((cut, mismatched.head(3), missing))

    if failures:
        print("  FAIL: unrelated future data changed labels that should be fixed.")
        for cut, examples, missing in failures[:3]:
            print(f"  Examples at cut {cut} (missing={missing}):")
            print(examples.to_string())
        return False
    print(f"  PASS: {total_checked:,} labels stayed unchanged after future-tail mutations.")
    return True


def main():
    args = parse_arguments()
    settings = make_settings(args)
    bars = load_bars(args.csv, args.resample)
    labels = generate_labels(bars, settings)
    label_rows = attach_row_number(bars, labels)

    print("\nMACD label audit")
    print(f"  Settings: {asdict(settings)}")
    print(f"  Generated labels: {len(labels):,}")
    report_time_integrity(bars, args.resample)
    report_effective_horizon(settings)
    report_distribution(labels)
    report_return_sanity(bars, label_rows, settings)
    passed = tail_independence_test(bars, labels, settings, args.trials)

    if args.labels_out:
        output = Path(args.labels_out)
        output.parent.mkdir(parents=True, exist_ok=True)
        labels.to_csv(output, index=False)
        print(f"\nSaved regenerated labels to {output}")
    if not passed:
        raise SystemExit("Leakage audit failed; do not train until it is investigated.")
    print("\nAudit completed: no future-tail leakage was detected.")


if __name__ == "__main__":
    main()

